</aside>

@push('scripts')

<script>
    const sidebar = document.getElementById("sidebar");
    const toggleBtn = document.getElementById("toggleSidebar");
    const toggleIcon = document.getElementById("toggleIcon");

    const logoFull = document.getElementById("logoFull");
    const logoIcon = document.getElementById("logoIcon");

    const sidebarLinks = document.querySelectorAll(".sidebar-link");
    const linkTexts = document.querySelectorAll(".link-text");
    const badges = document.querySelectorAll(".message-badge");


    const backButton = document.getElementById("backButton");
    const backText = document.querySelector(".back-text");
    const backIcon = document.querySelector(".back-icon");


    let collapsed = false;

    toggleBtn.addEventListener("click", () => {
        collapsed = !collapsed;

        if (collapsed) {
            // Collapse sidebar
            sidebar.classList.add("w-20");
            sidebar.classList.remove("w-64");

            toggleIcon.classList.replace("fa-chevron-left", "fa-chevron-right");

            logoFull.classList.add("hidden");
            logoIcon.classList.remove("hidden");

            linkTexts.forEach(text => text.classList.add("hidden"));
            badges.forEach(b => b.classList.add("hidden"));

            backText.classList.add("hidden");
            backIcon.classList.remove("hidden");

            backButton.classList.add("h-12", "w-12", "px-4", "rounded-full");
            backButton.classList.remove("w-full", "mx-auto");

            sidebarLinks.forEach(link => {
                link.setAttribute("title", link.querySelector(".link-text").textContent);
                link.classList.remove("px-4", "flex");
                link.classList.add("px-6", 'block');
            });

        } else {
            // Expand sidebar
            sidebar.classList.remove("w-20");
            sidebar.classList.add("w-64");

            toggleIcon.classList.replace("fa-chevron-right", "fa-chevron-left");

            logoIcon.classList.add("hidden");
            logoFull.classList.remove("hidden");

            linkTexts.forEach(text => text.classList.remove("hidden"));
            badges.forEach(b => b.classList.remove("hidden"));

            sidebarLinks.forEach(link => {
                link.setAttribute("title", link.querySelector(".link-text").textContent);
                link.classList.remove("px-6", 'block');
                link.classList.add("px-4", 'flex');
            });

            backText.classList.remove("hidden");
            backIcon.classList.add("hidden");

            backButton.classList.remove("h-12", "w-12", "p-0", "rounded-full");
            backButton.classList.add("w-full", "mx-auto", '');
        }
    });
</script>

@endpush